starter_query:
-- Column aliases with AS
SELECT product_name AS item_title, ...
FROM products;

-- Alias student columns
SELECT first_name AS fname, ...
FROM students;

-- Alias flight columns
SELECT flight_number AS flight_code, ...
FROM flights;

-- Alias account headers
SELECT account_id AS acct_no, ...
FROM accounts;

-- Stock aliases
SELECT symbol AS ticker, ...
FROM stocks;

-- Restaurant aliases
SELECT name AS restaurant_name, ...
FROM restaurants;

-- Doctor aliases
SELECT name AS practitioner, ...
FROM doctors;

-- Hotel aliases
SELECT name AS property_name, ...
FROM hotels;

-- Applicant aliases
SELECT first_name AS candidate_first, ...
FROM applicants;

-- Inventory aliases
SELECT sku AS product_code, ...
FROM stock_items;

-- Book aliases
SELECT title AS book_title, ...
FROM books;

-- Movie aliases
SELECT title AS film_title, ...
FROM movies;

-- Lead aliases
SELECT company_name AS client_name, ...
FROM leads;

-- Professor aliases
SELECT first_name AS given_name, ...
FROM professors;

-- Order aliases
SELECT order_id AS confirmation_number, ...
FROM orders;

-- Table alias e
SELECT e.first_name, e.last_name, e.job_title
FROM employees AS e;

-- Table alias p
SELECT p.product_id, p.product_name, p.price
FROM products AS p;

-- Table alias s
SELECT s.student_id, s.first_name, s.gpa
FROM students AS s;

-- Table alias f
SELECT f.flight_number, f.origin, f.destination
FROM flights AS f;

-- Table alias a
SELECT a.account_id, a.account_type, a.balance
FROM accounts AS a;

-- Table alias stk
SELECT stk.symbol, stk.company_name, stk.current_price
FROM stocks AS stk;

-- Table alias r
SELECT r.name, r.cuisine, r.rating
FROM restaurants AS r;

-- Table alias doc
SELECT doc.doctor_id, doc.name, doc.department
FROM doctors AS doc;

-- Combined aliases
SELECT h.name AS establishment, ...
FROM hotels AS h;

-- Combined aliases
SELECT b.title AS work_title, ...
FROM books AS b;

-- Combined aliases
SELECT m.title AS film, ...
FROM movies AS m;

-- Combined aliases
SELECT a.first_name AS given_name, ...
FROM applicants AS a;

-- Combined aliases
SELECT s.sku AS barcode, ...
FROM stock_items AS s;

-- Combined aliases
SELECT rep.name AS representative, ...
FROM sales_reps AS rep;
